function@blinds( $dashbaord : text ) : number
	var $blind = screen( $dashbaord, 1 )
	if input_number( $dashbaord, 0 ) == 1
		$blind.blank( color( 0, 0, 0, 0 ) )
	else
		$blind.blank( color( 0, 0, 0, 255 ) )
update

